#!/usr/bin/env bash
set -euo pipefail
WS="/home/kavia/workspace/code-generation/wifi-7-functional-test-plan-4457-4631/CoreDocumentation&GovernanceHub"
VENV="$WS/.venv"
cd "$WS"
# install requirements and pytest into venv using explicit pip
"$VENV/bin/pip" install --quiet --disable-pip-version-check -r requirements.txt pytest || { echo "pip install failed" >&2; exit 4; }
# verify pytest available
"$VENV/bin/pytest" --version >/dev/null 2>&1 || { echo "pytest not available in venv" >&2; exit 5; }
